        row[6] = if self.prone { 1.0 } else { 0.0 };
        row[7] = if self.r#use { 1.0 } else { 0.0 };
        row[8..8 + 2].copy_from_slice(&self.buttons);
        row[10] = if self.reload { 1.0 } else { 0.0 };
        row[11] = if self.next_primary { 1.0 } else { 0.0 };
        row[12] = if self.previous_primary { 1.0 } else { 0.0 };
        row[13] = if self.next_secondary { 1.0 } else { 0.0 };
        row[14] = if self.zoom { 1.0 } else { 0.0 };
        match &self.aim { Some(v) => { row[15] = 0.0; row[15 + 1..15 + 1 + 3].copy_from_slice(&(*v)); } None => { row[15] = 1.0; row[15 + 1..15 + 4].fill(0.0); } }
        match &self.jet_direction { Some(v) => { row[19] = 0.0; row[19 + 1..19 + 1 + 3].copy_from_slice(&(*v)); } None => { row[19] = 1.0; row[19 + 1..19 + 4].fill(0.0); } }
