#[derive(Clone, Debug, Default, PartialEq)]
pub struct RigAnimator {
    pub facing: f64,
    pub legs: f64,
    pub mode: f64,
    pub went_up_rolled: bool,
    pub roll_origin: f64,
    pub transition: f64,
    pub from: Vec<BonePose>,
    pub pivot: Vec3,
    pub roll_center: Vec3,
}

impl RigAnimator {
    pub const WORDS: usize = 14;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 14] = (&mut row[..14]).try_into().unwrap();
        row[0] = self.facing;
        row[1] = self.legs;
        row[2] = self.mode;
        row[3] = if self.went_up_rolled { 1.0 } else { 0.0 };
        row[4] = self.roll_origin;
        row[5] = self.transition;
        { let at = heap.len(); row[6] = at as f64; row[6 + 1] = self.from.len() as f64; heap.resize(at + self.from.len() * 7, 0.0); for (i, e) in self.from.iter().enumerate() { let mut item = [0.0f64; 7]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 7..at + (i + 1) * 7].copy_from_slice(&item); } }
        row[8..8 + 3].copy_from_slice(&self.pivot);
        row[11..11 + 3].copy_from_slice(&self.roll_center);
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 14] = (&row[..14]).try_into().unwrap();
        Self {
            facing: row[0],
            legs: row[1],
            mode: row[2],
            went_up_rolled: row[3] != 0.0,
            roll_origin: row[4],
            transition: row[5],
            from: { let (at, n) = (word_u32(row[6]) as usize, word_u32(row[6 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 7..at + (i + 1) * 7]; out.push(BonePose::take(&row[0..], heap)); } out },
            pivot: [row[8], row[8 + 1], row[8 + 2]],
            roll_center: [row[11], row[11 + 1], row[11 + 2]],
        }
    }

}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct UnitsPhaseUnit {
    pub unit: f64,
    pub remote: bool,
    pub edges: Option<Vec<CbEdge>>,
    pub edge: Option<CbEdge>,
    pub droideka_water: Option<DroidekaWater>,
}

impl UnitsPhaseUnit {
    pub const WORDS: usize = 20;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 20] = (&mut row[..20]).try_into().unwrap();
        row[0] = self.unit;
        row[1] = if self.remote { 1.0 } else { 0.0 };
        match &self.edges { Some(v) => { row[2] = 0.0; { let at = heap.len(); row[2 + 1] = at as f64; row[2 + 1 + 1] = v.len() as f64; heap.resize(at + v.len() * 9, 0.0); for (i, e) in v.iter().enumerate() { let mut item = [0.0f64; 9]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 9..at + (i + 1) * 9].copy_from_slice(&item); } } } None => { row[2] = 1.0; row[2 + 1..2 + 3].fill(0.0); } }
        match &self.edge { Some(v) => { row[5] = 0.0; v.put(&mut row[5 + 1..], heap); } None => { row[5] = 1.0; row[5 + 1..5 + 10].fill(0.0); } }
        match &self.droideka_water { Some(v) => { row[15] = 0.0; v.put(&mut row[15 + 1..], heap); } None => { row[15] = 1.0; row[15 + 1..15 + 5].fill(0.0); } }
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 20] = (&row[..20]).try_into().unwrap();
        Self {
            unit: row[0],
            remote: row[1] != 0.0,
            edges: if row[2] == 0.0 { Some({ let (at, n) = (word_u32(row[2 + 1]) as usize, word_u32(row[2 + 1 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 9..at + (i + 1) * 9]; out.push(CbEdge::take(&row[0..], heap)); } out }) } else { None },
            edge: if row[5] == 0.0 { Some(CbEdge::take(&row[5 + 1..], heap)) } else { None },
            droideka_water: if row[15] == 0.0 { Some(DroidekaWater::take(&row[15 + 1..], heap)) } else { None },
        }
    }

}

