        row[18] = self.collision_damage;
        row[19..19 + 3].copy_from_slice(&self.position);
        row[22..22 + 3].copy_from_slice(&self.previous);
        row[25..25 + 3].copy_from_slice(&self.settled);
        row[28..28 + 3].copy_from_slice(&self.velocity);
        row[31..31 + 3].copy_from_slice(&self.avoidance);
        row[34] = self.aim_yaw;
        row[35] = self.aim_pitch;
        row[36] = self.state_time;
        row[37] = if self.grounded { 1.0 } else { 0.0 };
        row[38] = self.look_x;
        row[39] = self.look_y;
        row[40] = self.mode;
        row[41] = self.time;
        row[42] = if self.reverse { 1.0 } else { 0.0 };
