        row[44] = self.spin;
        row[45] = self.roll;
        row[46] = self.lean;
        row[47] = if self.dead { 1.0 } else { 0.0 };
        row[48] = self.blast_clock;
        row[49] = self.gun;
        match &self.last_gun { Some(v) => { row[50] = 0.0; v.put(&mut row[50 + 1..], heap); } None => { row[50] = 2.0; row[50 + 1..50 + 3].fill(0.0); } }
        match &self.shield { Some(v) => { row[53] = 0.0; v.put(&mut row[53 + 1..], heap); } None => { row[53] = 1.0; row[53 + 1..53 + 7].fill(0.0); } }
        match &self.water_clock { Some(v) => { row[60] = 0.0; row[60 + 1] = (*v); } None => { row[60] = 2.0; row[60 + 1..60 + 2].fill(0.0); } }
